import{_ as s,o as a,c as t,a2 as i}from"./chunks/framework.BXzK3EA4.js";const k=JSON.parse('{"title":"Version 2.0.0.9 Released","description":"","frontmatter":{},"headers":[],"relativePath":"change-log/release/version-2.0.0.9-released.md","filePath":"change-log/release/version-2.0.0.9-released.md"}'),n={name:"change-log/release/version-2.0.0.9-released.md"};function o(r,e,p,l,d,h){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="version-2-0-0-9-released" tabindex="-1">Version 2.0.0.9 Released <a class="header-anchor" href="#version-2-0-0-9-released" aria-label="Permalink to &quot;Version 2.0.0.9 Released&quot;">​</a></h1><p><strong>Date: 1st May 2026</strong></p><p><strong>Patch: Manual-Rotation Guidance Hardened — Never Recommend Rotating <code>API_KEY_PEPPER</code> on a Populated Database</strong></p><p>This is a <strong>single-commit patch release</strong> on top of v2.0.0.8&#39;s Docker upgrade hotfix. The auto-rotation in <code>utils/env_check.py</code> already gates <code>API_KEY_PEPPER</code> rotation on database state — it only rotates the pepper on a fresh install with no users, because rotating it on a populated DB would invalidate every Argon2 password hash and every Fernet-encrypted broker auth/feed token / TradingView API key, none of which can be recovered. But the <strong>fallback error-path messaging</strong> — printed when the rotation cannot write to <code>.env</code> (e.g. read-only mount, permission denied) — was still telling users to manually regenerate <em>both</em> values. A user with a populated DB who followed that recipe would brick their deployment. Same problem in the <code>start.sh</code> pre-flight banner added in v2.0.0.8. v2.0.0.9 makes the user-facing manual-rotation guidance match the auto-rotation gating.</p><hr><p><strong>Highlights</strong></p><ul><li><strong>Error path now DB-aware</strong> — <code>utils/env_check.py</code> branches the manual-rotation message on <code>db_populated</code>. Populated DB → instructs only <code>APP_KEY</code> rotation, with an explicit &quot;DO NOT change <code>API_KEY_PEPPER</code>&quot; warning and a pointer to <code>upgrade/rotate_pepper.py</code>. Fresh DB → both can be safely regenerated.</li><li><strong><code>start.sh</code> pre-flight banner rewritten</strong> — Default advice is <code>APP_KEY</code>-only. A second prominent block warns against regenerating <code>API_KEY_PEPPER</code> with the reasoning, and points to <code>upgrade/rotate_pepper.py</code> for the controlled path.</li></ul><hr><p><strong>Security</strong></p><ul><li><code>b9301b78</code> — <code>fix(security): never recommend rotating API_KEY_PEPPER on populated DB</code></li></ul><p>The auto-rotation logic in <code>utils/env_check.py:329-412</code> is correct: on a populated DB, only <code>APP_KEY</code> is rotated; <code>API_KEY_PEPPER</code> is deliberately left alone because rotating the pepper invalidates:</p><ul><li>Every Argon2 password hash in <code>database/user_db.py</code> (one-way, cannot be migrated).</li><li>Every Fernet-encrypted broker auth/feed token in <code>database/auth_db.py</code>.</li><li>Every Fernet-encrypted TradingView API key.</li></ul><p>But the <strong>fallback error-path</strong> — taken when the rotation can&#39;t write <code>.env.tmp</code> (read-only mount, EACCES) — printed:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Detected publicly-known APP_KEY/API_KEY_PEPPER in .env, but</span></span>
<span class="line"><span>could not rewrite the file (...).</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Generate fresh values manually and paste them into .env:</span></span>
<span class="line"><span>  python -c &quot;import secrets; print(secrets.token_hex(32))&quot;</span></span></code></pre></div><p>That advice is safe on a fresh install, fatal on a populated one. Same issue in the <code>start.sh</code> pre-flight banner added in v2.0.0.8 — it instructed users to <code>sed</code>-replace both <code>APP_KEY</code> and <code>API_KEY_PEPPER</code>.</p><p>Fixes shipped:</p><ul><li><p><strong><code>utils/env_check.py</code></strong> — error message branches on <code>db_populated</code>. Populated DB prints <code>APP_KEY</code>-only instructions plus an explicit, bold &quot;DO NOT change <code>API_KEY_PEPPER</code> on this populated install&quot; warning, with the reasoning and a pointer to <code>upgrade/rotate_pepper.py</code> for the controlled rotation path that handles re-encryption + password reset. Fresh DB prints the original &quot;both can be regenerated&quot; guidance.</p></li><li><p><strong><code>start.sh</code></strong> — pre-flight banner rewritten. Default action is <code>APP_KEY</code>-only:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">APP_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;import secrets; print(secrets.token_hex(32))&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sed</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;s|^APP_KEY *=.*|APP_KEY = &#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$APP_KEY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;|&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chown</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 1000:1000</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chmod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 600</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span></span></code></pre></div><p>A second prominent banner block — <code>[Tradeboard] DO NOT regenerate API_KEY_PEPPER</code> — explains why and points to the rotate_pepper.py migration. PEPPER rotation is only safe on installs with no users; on any other install, leave it alone and let the auto-rotation&#39;s silent fast path take over once <code>APP_KEY</code> is no longer compromised.</p></li></ul><p>The <code>_generate_keys_on_first_run</code> decision matrix (already documented in <code>utils/env_check.py:332-345</code>) is unchanged. v2.0.0.9 only tightens the <em>user-facing manual-rotation guidance</em> to mirror the same gating.</p><p><strong>Safe upgrade procedure for users on a populated install hitting the v2.0.0.6 → v2.0.0.8 Docker crash:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> down</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">APP_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;import secrets; print(secrets.token_hex(32))&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sed</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;s|^APP_KEY *=.*|APP_KEY = &#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$APP_KEY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;|&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Do NOT touch API_KEY_PEPPER on a populated DB.</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chown</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 1000:1000</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chmod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 600</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div><p>After this, <code>_generate_keys_on_first_run</code> takes the silent fast path for <code>APP_KEY</code> (no longer in <code>COMPROMISED_APP_KEYS</code>). The pepper remains in the compromised set, but <code>db_populated=True</code> gates the rotation off — only a single warning line, no startup block. Browser sessions need to log in again — by-design, that&#39;s how <code>APP_KEY</code> rotation prevents anyone with the leaked sample key from forging your sessions.</p><hr><p><strong>Contributors</strong></p><ul><li><strong>@marketcalls (Rajandran)</strong> — security hardening of manual-rotation guidance; PEPPER-safety review against the populated-DB upgrade path.</li></ul><hr><p><strong>Links</strong></p><ul><li><strong>Repository</strong>: <a href="https://github.com/wesoftcorp/tradeboard-docs" target="_blank" rel="noreferrer">https://github.com/wesoftcorp/tradeboard-docs</a></li><li><strong>Documentation</strong>: <a href="https://docs.algo.wesoftcorp.com" target="_blank" rel="noreferrer">https://docs.algo.wesoftcorp.com</a></li><li><strong>Discord</strong>: <a href="https://www.tradeboard.in/discord" target="_blank" rel="noreferrer">https://www.tradeboard.in/discord</a></li><li><strong>Issue tracker</strong>: <a href="https://github.com/wesoftcorp/tradeboard-docs/issues" target="_blank" rel="noreferrer">https://github.com/wesoftcorp/tradeboard-docs/issues</a></li></ul><hr>`,28)])])}const g=s(n,[["render",o]]);export{k as __pageData,g as default};
